def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    danger = 0
    if hp <= 2:
        danger = 3
    elif hp <= 4:
        danger = 2
    elif hp <= 6:
        danger = 1

    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1

    base = 22.0
    if scarcity == 1:
        base = 34.0
    elif scarcity == 2:
        base = 48.0

    if highest_prev >= 120:
        if danger >= 3:
            bid = 96.0
        elif scarcity == 2:
            bid = 58.0
        else:
            bid = 24.0
    elif highest_prev >= 90:
        if danger >= 3:
            bid = highest_prev + 2.0
        elif danger >= 2:
            bid = max(base + 10.0, avg_prev * 0.72)
        else:
            bid = max(26.0, avg_prev * 0.45)
    else:
        bid = max(base, highest_prev + 1.5 if highest_prev > 0 else base)

    if urgent_opp >= 2 and danger == 0:
        bid *= 0.82
    if rich_opp >= 2 and scarcity >= 1 and danger >= 2:
        bid *= 1.12

    if day >= 8:
        if danger >= 2:
            bid *= 1.15
        else:
            bid *= 0.92

    if hp >= 8 and no_water_days == 0 and scarcity == 0:
        bid = min(bid, 28.0)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, 78.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, 52.0 if scarcity == 0 else 68.0)

    reserve = 0.0
    if day <= 7:
        reserve = 35.0
    elif day <= 9:
        reserve = 15.0

    spend_cap = budget - reserve
    if spend_cap < 0:
        spend_cap = budget

    bid = min(bid, spend_cap)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # React to yesterday's immediate pressure
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply-aware target: if supply is low, competition is higher; bid more.
    # With WATER_REQ=9, supply 15-25 means roughly 1-2 water units available.
    # Use a smooth scaling between 55% and 80% of salary.
    if supply <= float(MIN_SUPPLY):
        supply_factor = 0.80
    elif supply >= float(MAX_SUPPLY):
        supply_factor = 0.60
    else:
        # linear interpolation
        supply_factor = 0.80 - (supply - float(MIN_SUPPLY)) * (0.20 / (float(MAX_SUPPLY) - float(MIN_SUPPLY)))

    # If yesterday someone bid extremely high (~near 160), avoid matching; aim just below.
    # If yesterday pressure was moderate, bid to beat it.
    pressure_threshold = DAILY_SALARY * 0.85  # 76.5

    if highest_prev_bid >= pressure_threshold:
        # Avoid suicidal chase: take a capped response.
        target = min(DAILY_SALARY * supply_factor, highest_prev_bid - 5.0)
        # If our HP is critical or we've been without water, increase slightly.
        if hp <= 2 or no_water_days >= 2:
            target = min(budget, max(target, DAILY_SALARY * 0.75))
    else:
        # Lower pressure: bid around supply_factor*salary, but slightly above baseline.
        target = DAILY_SALARY * (supply_factor + 0.05)
        if hp <= 2 or no_water_days >= 2:
            target = max(target, DAILY_SALARY * 0.70)

    # Ensure we don't overspend: never exceed budget.
    # Also keep a floor to remain competitive when supply is low.
    floor_bid = DAILY_SALARY * 0.35 if supply > float(MIN_SUPPLY) else DAILY_SALARY * 0.55
    target = max(floor_bid, target)

    # Final clamp
    if budget <= 0:
        return 0.0
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    days_remaining = EPISODE_DAYS - current_day

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = DAILY_SALARY * 0.65 

    if not yesterday_bids:
        if my_hp <= 3:
            bid = DAILY_SALARY * 0.9
        elif my_hp <= 5:
            bid = DAILY_SALARY * 0.8
        else:
            bid = DAILY_SALARY * 0.7
    else:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_hp <= 3:
                bid = max(highest_prev_bid + 10, DAILY_SALARY * 0.98)
            elif my_hp <= 5:
                bid = max(highest_prev_bid + 5, DAILY_SALARY * 0.9)
            else:
                bid = max(highest_prev_bid * 0.95, DAILY_SALARY * 0.7)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            if my_hp <= 4:
                bid = max(highest_prev_bid + 3, DAILY_SALARY * 0.8)
            else:
                bid = max(highest_prev_bid + 1, DAILY_SALARY * 0.65)
        else:
            bid = max(highest_prev_bid + 1, DAILY_SALARY * 0.4)

    if my_hp <= 2:
        bid = max(bid, DAILY_SALARY * 1.0)
    elif my_hp <= 4:
        bid = max(bid, DAILY_SALARY * 0.9)

    if days_remaining <= 2:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif days_remaining <= 4:
        bid = max(bid, DAILY_SALARY * 0.8)

    if current_supply <= 17:
        bid *= 1.1
    elif current_supply >= 23:
        if my_hp > 5 and days_remaining > 3:
            bid *= 0.9

    final_bid = min(my_budget, bid)

    return max(0.1, final_bid)
